import { base64UrlDecode, base64UrlEncode, bytesToUtf8, utf8ToBytes } from '../encoding/base64url.mjs';
import { hmacSha256 } from '../hash/hmacSha256.mjs';

function normalizeSecret(secret) {
  return typeof secret === 'string' ? utf8ToBytes(secret) : Uint8Array.from(secret);
}

function encodeSegment(value) {
  return base64UrlEncode(utf8ToBytes(JSON.stringify(value)));
}

function constantTimeEqual(left, right) {
  if (left.length !== right.length) {
    return false;
  }

  let mismatch = 0;
  for (let index = 0; index < left.length; index += 1) {
    mismatch |= left.charCodeAt(index) ^ right.charCodeAt(index);
  }
  return mismatch === 0;
}

function validateIssuedAt(payload) {
  if (!Object.prototype.hasOwnProperty.call(payload, 'iat')) {
    return;
  }

  const issuedAt = payload.iat;
  if (typeof issuedAt === 'number' && Number.isInteger(issuedAt)) {
    return;
  }
  if (typeof issuedAt === 'string' && /^[+-]?\d+$/u.test(issuedAt.trim())) {
    return;
  }

  throw new Error('Issued At claim (iat) must be an integer.');
}

export function encodeJwt(payload, secret) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const encodedHeader = encodeSegment(header);
  const encodedPayload = encodeSegment(payload);
  const signingInput = `${encodedHeader}.${encodedPayload}`;
  const signature = hmacSha256(normalizeSecret(secret), utf8ToBytes(signingInput));
  return `${signingInput}.${base64UrlEncode(signature)}`;
}

export function decodeJwt(token, secret, options = {}, algorithms = ['HS256']) {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Not enough segments');
  }

  const [encodedHeader, encodedPayload, encodedSignature] = parts;
  const header = JSON.parse(bytesToUtf8(base64UrlDecode(encodedHeader)));
  if (!Array.isArray(algorithms) || !algorithms.includes(header.alg)) {
    throw new Error('The specified alg value is not allowed');
  }
  if (header.alg !== 'HS256') {
    throw new Error('Algorithm not supported');
  }

  const signingInput = `${encodedHeader}.${encodedPayload}`;
  const expectedSignature = base64UrlEncode(
    hmacSha256(normalizeSecret(secret), utf8ToBytes(signingInput)),
  );
  if (!constantTimeEqual(encodedSignature, expectedSignature)) {
    throw new Error('Signature verification failed');
  }

  const payload = JSON.parse(bytesToUtf8(base64UrlDecode(encodedPayload)));
  if (options.verify_iat !== false) {
    validateIssuedAt(payload);
  }

  return payload;
}

