import { CliExit, getProgramName, parseTest17Args } from './lib/cli/test17Args.mjs';
import { pythonRepr } from './lib/format/pythonRepr.mjs';
import { decodeJwt, encodeJwt } from './lib/jwt/hs256.mjs';

const SECRET = 'secret';

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const programName = getProgramName(scriptPath);
  const args = parseTest17Args(argv, programName);

  const payload = {
    info: args.data,
    iat: Math.floor(Date.now() / 1000),
  };
  const token = encodeJwt(payload, SECRET);
  process.stdout.write(`${token}\n`);

  const verifyIat = args.verify_iat === 'true';
  const decoded = decodeJwt(token, SECRET, { verify_iat: verifyIat }, ['HS256']);
  process.stdout.write(`${pythonRepr(decoded)}\n`);
}

function handleCliExit(error) {
  const stream = error.stream === 'stdout' ? process.stdout : process.stderr;
  stream.write(error.output);
  process.exitCode = error.status;
}

