function pythonStringRepr(value) {
  let result = "'";

  for (const character of value) {
    if (character === '\\') {
      result += '\\\\';
      continue;
    }
    if (character === "'") {
      result += "\\'";
      continue;
    }
    if (character === '\n') {
      result += '\\n';
      continue;
    }
    if (character === '\r') {
      result += '\\r';
      continue;
    }
    if (character === '\t') {
      result += '\\t';
      continue;
    }
    if (character === '\b') {
      result += '\\b';
      continue;
    }
    if (character === '\f') {
      result += '\\f';
      continue;
    }

    const codePoint = character.codePointAt(0);
    if (codePoint < 0x20 || codePoint === 0x7f) {
      result += `\\x${codePoint.toString(16).padStart(2, '0')}`;
      continue;
    }

    result += character;
  }

  return `${result}'`;
}

export function pythonRepr(value) {
  if (typeof value === 'string') {
    return pythonStringRepr(value);
  }
  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : 'None';
  }
  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }
  if (value === null || value === undefined) {
    return 'None';
  }
  if (Array.isArray(value)) {
    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`;
  }
  if (typeof value === 'object') {
    const entries = Object.entries(value).map(
      ([key, entryValue]) => `${pythonRepr(key)}: ${pythonRepr(entryValue)}`,
    );
    return `{${entries.join(', ')}}`;
  }

  return pythonStringRepr(String(value));
}

